static int N;
static unsigned long long *factv;

unsigned long long rank_perm(int *p) {
    int used[10] = {0};
    unsigned long long rank = 0;
    for (int i = 0; i < N; i++) {
        int smaller = 0;
        for (int v = 1; v < p[i]; v++) {
            if (!used[v]) smaller++;
        }
        rank += (unsigned long long)smaller * factv[N - 1 - i];
        used[p[i]] = 1;
    }
    return rank;
}

void reverse_seg(int *src, int *dst, int l, int r) {
    for (int i = 0; i < N; i++) dst[i] = src[i];
    while (l < r) {
        int t = dst[l];
        dst[l] = dst[r];
        dst[r] = t;
        l++;
        r--;
    }
}

int is_sorted(int *p) {
    for (int i = 0; i < N; i++) {
        if (p[i] != i + 1) return 0;
    }
    return 1;
}

int main() {
    if (scanf("%d", &N) != 1) return 0;

    int *start = (int *)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) scanf("%d", &start[i]);

    if (is_sorted(start)) {
        printf("0\n");
        free(start);
        return 0;
    }

    factv = (unsigned long long *)malloc((N + 1) * sizeof(unsigned long long));
    factv[0] = 1;
    for (int i = 1; i <= N; i++) factv[i] = factv[i - 1] * (unsigned long long)i;

    unsigned long long total_states = factv[N];

    /* BFS over all permutations */
    int *queue_data = (int *)malloc((size_t)total_states * N * sizeof(int));
    int *queue_dist = (int *)malloc((size_t)total_states * sizeof(int));

    /* hash table */
    unsigned long long hsize = 1;
    while (hsize < total_states * 2) hsize <<= 1;
    Entry *table = (Entry *)calloc((size_t)hsize, sizeof(Entry));

    /* push start */
    memcpy(queue_data, start, N * sizeof(int));
    queue_dist[0] = 0;

    unsigned long long code = rank_perm(start);
    unsigned long long pos = code & (hsize - 1);
    while (table[pos].used) pos = (pos + 1) & (hsize - 1);
    table[pos].used = 1;
    table[pos].key = queue_data;
    table[pos].dist = 0;

    unsigned long long head = 0, tail = 1;
    int *tmp = (int *)malloc(N * sizeof(int));

    while (head < tail) {
        int *cur = queue_data + head * N;
        int cd = queue_dist[head];
        head++;

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                reverse_seg(cur, tmp, i, j);

                if (is_sorted(tmp)) {
                    printf("%d\n", cd + 1);
                    free(start);
                    free(factv);
                    free(queue_data);
                    free(queue_dist);
                    free(table);
                    free(tmp);
                    return 0;
                }

                unsigned long long r = rank_perm(tmp);
                unsigned long long h = r & (hsize - 1);
                int found = 0;
                while (table[h].used) {
                    if (rank_perm(table[h].key) == r) {
                        found = 1;
                        break;
                    }
                    h = (h + 1) & (hsize - 1);
                }
                if (!found) {
                    memcpy(queue_data + tail * N, tmp, N * sizeof(int));
                    queue_dist[tail] = cd + 1;
                    table[h].used = 1;
                    table[h].key = queue_data + tail * N;
                    table[h].dist = cd + 1;
                    tail++;
                }
            }
        }
    }

