/*
We need the minimum number of subarray reversals to sort a permutation.

Observation:
A reversal can fix any contiguous block, but finding the exact minimum for arbitrary N
is hard in general. However, for permutations, there is a classic exact formulation using
BFS on permutation states, which is feasible only for small N.

Since the statement provides no explicit constraints, we use the standard exact approach
for small/medium N by bidirectional BFS on permutation states encoded compactly.
This is the common intended solution when constraints are around N <= 8..10.

State encoding:
Use Lehmer code / factorial number system to rank each permutation uniquely in [0, N!-1].

Transitions:
From each permutation, try all reversals (i, j), i < j.

We run bidirectional BFS from:
- start permutation
- target sorted permutation

Answer is the first meeting distance.

If N <= 1, answer is 0.
*/

static long long fact_[13];

long long rank_perm(const vector<int>& p) {
    int n = (int)p.size();
    long long rank = 0;
    vector<int> used(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        int smaller_unused = 0;
        for (int x = 1; x < p[i]; ++x) {
            if (!used[x]) ++smaller_unused;
        }
        rank += smaller_unused * fact_[n - 1 - i];
        used[p[i]] = 1;
    }
    return rank;
}

vector<int> unrank_perm(long long rank, int n) {
    vector<int> nums;
    for (int i = 1; i <= n; ++i) nums.push_back(i);
    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        long long block = fact_[n - 1 - i];
        int idx = (int)(rank / block);
        rank %= block;
        p[i] = nums[idx];
        nums.erase(nums.begin() + idx);
    }
    return p;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    fact_[0] = 1;
    for (int i = 1; i <= 12; ++i) fact_[i] = fact_[i - 1] * i;

    int N;
    cin >> N;
    vector<int> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    vector<int> target(N);
    iota(target.begin(), target.end(), 1);

    if (a == target) {
        cout << 0 << '\n';
        return 0;
    }

    // Exact approach is practical only when N! is manageable.
    // This solution targets the standard small-N version of the problem.
    long long total = fact_[N];

    long long start_rank = rank_perm(a);
    long long target_rank = rank_perm(target);

    vector<short> dist1(total, -1), dist2(total, -1);
    queue<long long> q1, q2;

    dist1[start_rank] = 0;
    dist2[target_rank] = 0;
    q1.push(start_rank);
    q2.push(target_rank);

    auto expand = [&](queue<long long>& q, vector<short>& da, vector<short>& db) -> int {
        int qs = (int)q.size();
        while (qs--) {
            long long cur = q.front();
            q.pop();

            vector<int> p = unrank_perm(cur, N);
            int d = da[cur];

            for (int i = 0; i < N; ++i) {
                for (int j = i + 1; j < N; ++j) {
                    reverse(p.begin() + i, p.begin() + j + 1);
                    long long nr = rank_perm(p);
                    if (da[nr] == -1) {
                        da[nr] = d + 1;
                        if (db[nr] != -1) return da[nr] + db[nr];
                        q.push(nr);
                    }
                    reverse(p.begin() + i, p.begin() + j + 1);
                }
            }
        }
        return -1;
    };

    while (!q1.empty() && !q2.empty()) {
        int ans;
        if (q1.size() <= q2.size()) {
            ans = expand(q1, dist1, dist2);
        } else {
            ans = expand(q2, dist2, dist1);
        }
        if (ans != -1) {
            cout << ans << '\n';
            return 0;
        }
    }

    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        int breakpoints = 0;
        // Check before first element
        if (arr[0] != 1) breakpoints++;
        // Check between elements
        for (int i = 0; i < n - 1; i++) {
            if (Math.abs(arr[i] - arr[i + 1]) != 1) {
                breakpoints++;
            }
        }
        // Check after last element
        if (arr[n - 1] != n) breakpoints++;

        // Each reversal can fix at most 2 breakpoints
        int result = (breakpoints + 1) / 2;
        System.out.println(result);
    }
}

